import IniciarSesion from '../../Componentes/Formularios/IniciarSesion/IniciarSesion';
import './InicioSesion.css'
import leyseca from '../../assets/leysecalogo2.png'

export default function InicioSesion() {
    return (
        <>
            <div className="__topbar">
                <div className="__topbar_logo_seccion">
                    <img src={leyseca} alt="Ley Seca" className="__topbar_logo" />
                    <span className="__topbar_nombre_empresa">LEY SECA</span>
                </div>
            </div>
            <IniciarSesion></IniciarSesion>
        </>
    );

}