import { useForm } from "react-hook-form"
import './IniciarSesion.css'
import { useNavigate } from 'react-router-dom';
import { useState } from "react";
import { useUsuarioStore } from "../../../store/Usuario";
import ResetearContrasena from "../ResetearContrasenia/ResetearContrasenia";
import RecuperarContrasenia from "../RecuperarContrasenia/RecuperarContrasenia";
import Modal from "../../Modal/Modal";



export default function IniciarSesion() {
    const navegarHacia = useNavigate();
    const iniciarSesion = useUsuarioStore((state) => state.iniciarSesion);
    const { register, handleSubmit, formState: { errors } } = useForm({

    });

    const [modalRecuperarContrasenia, setModalRecuperarContrasenia] = useState(false);
    const manejaModalRecuperarContrasenia = ()=>{
       setModalRecuperarContrasenia(!modalRecuperarContrasenia);
    }

    const onSubmit = async (data) => {
        manejaCargando(true);
        try {
            // 🔹 Usamos la función del store
            const resultado = await iniciarSesion(data.correo, data.contraseña);

            if (resultado?.token) {
                navegarHacia('/productos');
            } else {
                alert("Usuario o contraseña incorrectos");
            }

        } catch (error) {
            console.error("Error al iniciar sesión:", error);
            alert("Usuario o contraseña incorrectos");
        }
        finally {
            setCargando(false);
        }
    }

    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
    const [cargando, setCargando] = useState(false);

    const manejaCargando = ((valor) => {
        setCargando(valor);
    });

    //LAYOUT

    return (
        <>
            {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
            <div className="formLogin">
                <div id="inicio"> <h2>Inicio de Sesion</h2>
                </div>
                <form onSubmit={handleSubmit(onSubmit)}                 >
                    <div className="boxInput">
                        <input type="text"
                            {...register("correo", {
                                required: {
                                    value: true,
                                    message: "Ingrese nombre Usuario"
                                }
                            })}
                        ></input>
                        <label>Correo</label>
                        <span></span>
                    </div>
                    <div className="boxInput">
                        <input type="password"
                            {...register("contraseña", {
                                required: {
                                    value: true,
                                    message: "Ingrese Contraseña"
                                }
                            })}
                        ></input>
                        <label>Contraseña</label>
                        <span></span>
                    </div>
                    <div>

                        <input id="bottomIniciar" type="submit" value="Iniciar"></input>
                    </div>
                    <div className="rememberPassword">
                        <button onClick={manejaModalRecuperarContrasenia}>¿Olvidaste tu contraseña?</button>
                    </div>
                </form>
            </div>
              <Modal visible={modalRecuperarContrasenia}
               titulo="Recuperar Contraseña" 
               funcion={manejaModalRecuperarContrasenia}
               anchura="500px"
               >
                <RecuperarContrasenia onCerrar={manejaModalRecuperarContrasenia}>  </RecuperarContrasenia>
              </Modal>
            <script src="script.js"></script>
        </>
    );
}